/// CLI command execution helper — Dart port of Java `CliExecutionHelper`.
///
/// Handles environment-variable filtering, subprocess execution, and output
/// response extraction. Used by [CliAgent] for the `cliCommands` phase.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import '../integrations/cli/process_output_tee.dart';

/// The output response file name (both folders use the same file).
const String responseFileName = 'response.md';

/// Cap, in characters, of the log excerpt embedded in the response of a
/// FAILED CLI run.
///
/// The extracted response is published verbatim by post-actions (PR/ticket
/// comments, PR descriptions). A failed agent run's full session log must
/// never leak into it — only a bounded head+tail excerpt is embedded
/// (gh-192); the complete log stays in the run output.
const int boundedResponseLogCap = 4000;

/// Returns [log] trimmed, bounded to at most [cap] characters.
///
/// Logs longer than [cap] keep their first `cap ~/ 2` characters and their
/// last `cap - cap ~/ 2` characters, joined by an explicit truncation
/// marker — failures announce themselves at the start (command line, exit
/// code) and their cause is usually at the end, while the middle (the full
/// session transcript) is noise for a human reading the posted response.
String boundedLog(String log, {int cap = boundedResponseLogCap}) {
  final text = log.trim();
  if (text.length <= cap) return text;
  final headLength = cap ~/ 2;
  final tailLength = cap - headLength;
  final omitted = text.length - headLength - tailLength;
  return '${text.substring(0, headLength)}\n'
      '[... truncated $omitted characters — full session log in the run '
      'output ...]\n'
      '${text.substring(text.length - tailLength)}';
}

/// Folder preference when reading the output response.
enum OutputFolderPreference {
  /// Check `output/` first, then `outputs/`.
  legacyOutputFirst,

  /// Check `outputs/` first, then `output/`.
  outputsFirst,
}

/// Result container for a CLI command batch.
class CliExecutionResult {
  /// Creates a result with accumulated [commandResponses] and optional
  /// [outputResponse].
  CliExecutionResult({
    required this.commandResponses,
    this.outputResponse,
    this.hasFatalError = false,
    this.lastExitCode,
    this.lastErrorMessage,
  });

  /// Accumulated stdout/stderr from all commands.
  final String commandResponses;

  /// Content of `outputs/response.md` (or legacy `output/response.md`).
  final String? outputResponse;

  /// True if any command failed with a non-zero exit code.
  final bool hasFatalError;

  /// Exit code of the last failing command, or null.
  final int? lastExitCode;

  /// Error message from the last failing command, or null.
  final String? lastErrorMessage;

  /// Returns true when [outputResponse] is non-null and non-empty.
  bool get hasOutputResponse =>
      outputResponse != null && outputResponse!.trim().isNotEmpty;
}

/// Mutable holder for the live CLI-output snapshot.
///
/// Dart port of the Java `AtomicReference<String> liveOutput`: updated after
/// every output line and after each command so a concurrent timer JS action
/// can observe partial output.
class LiveCliOutput {
  /// Current accumulated output snapshot.
  String value = '';
}

/// Hooks for monitored CLI execution.
///
/// Dart port of the Java `executeCliCommandsWithResult` overload that accepts a
/// timer action, an error handler, and a per-line stop predicate. When any hook
/// is set, [CliExecutionHelper.executeCommandsWithCallbacks] streams each
/// command's merged stdout/stderr line-by-line instead of buffering.
class CliExecutionCallbacks {
  /// Creates a callbacks bundle.
  const CliExecutionCallbacks({
    this.timerAction,
    required this.timerIntervalSeconds,
    this.errorHandler,
    this.lineStopPredicate,
    this.liveOutput,
  });

  /// Fired every [timerIntervalSeconds] during execution and once more after
  /// the batch completes (final tick).
  final void Function()? timerAction;

  /// Seconds between timer firings; no timer when `<= 0`.
  final int timerIntervalSeconds;

  /// Invoked with the formatted error message when a command exits non-zero.
  final void Function(String errorMessage)? errorHandler;

  /// Invoked per output line; returning `true` kills the process and aborts
  /// the remaining command batch.
  final bool Function(String line)? lineStopPredicate;

  /// Shared live-output snapshot updated after each line/command.
  final LiveCliOutput? liveOutput;

  /// True when at least one hook is configured.
  bool get hasHooks =>
      timerAction != null || errorHandler != null || lineStopPredicate != null;
}

/// Executes CLI commands with environment filtering and output collection.
class CliExecutionHelper {
  /// Creates a helper.
  const CliExecutionHelper();

  // ------------------------------------------------------------------
  // Environment filtering
  // ------------------------------------------------------------------

  /// Filters [envVars] by removing exact-name and regex-matched keys.
  ///
  /// Returns a new map. When both filters are null/empty, returns the
  /// original map unchanged.
  ///
  /// Mirrors `CliExecutionHelper.filterEnvVariables()`.
  static Map<String, String> filterEnvVariables(
    Map<String, String> envVars,
    List<String>? excludedEnvVariables,
    List<String>? excludedEnvRegexes,
  ) {
    if (envVars.isEmpty) return envVars;

    final exact = _buildExactExclusions(excludedEnvVariables);
    final regexes = _compileRegexes(excludedEnvRegexes);
    if (exact.isEmpty && regexes.isEmpty) return envVars;

    return _applyFilters(envVars, exact, regexes);
  }

  static Set<String> _buildExactExclusions(List<String>? names) {
    if (names == null) return const {};
    return names.where((n) => n.trim().isNotEmpty).toSet();
  }

  static List<RegExp> _compileRegexes(List<String>? patterns) {
    if (patterns == null) return const [];
    return patterns
        .where((p) => p.trim().isNotEmpty)
        .map((p) => RegExp(p))
        .toList();
  }

  static Map<String, String> _applyFilters(
    Map<String, String> envVars,
    Set<String> exact,
    List<RegExp> regexes,
  ) {
    final filtered = <String, String>{};
    for (final entry in envVars.entries) {
      if (exact.contains(entry.key)) continue;
      if (regexes.any((r) => r.hasMatch(entry.key))) continue;
      filtered[entry.key] = entry.value;
    }
    return filtered;
  }

  // ------------------------------------------------------------------
  // Command execution
  // ------------------------------------------------------------------

  /// Executes [commands] sequentially, accumulating output.
  ///
  /// Each command is run via `/bin/sh -c` to allow arbitrary shell syntax.
  /// [workingDirectory] sets the subprocess CWD. [environment] replaces the
  /// inherited OS env when non-null. Every output line is mirrored live to
  /// dmtools' stderr while it streams ([mirror] overrides the target for
  /// tests) — the captured `commandResponses` stay byte-identical.
  ///
  /// Returns a [CliExecutionResult] with accumulated responses and the
  /// output response file content (if present).
  Future<CliExecutionResult> executeCommands(
    List<String> commands, {
    String? workingDirectory,
    Map<String, String>? environment,
    OutputFolderPreference preference = OutputFolderPreference.outputsFirst,
    OutputLineSink? mirror,
  }) async {
    final responses = StringBuffer();
    var hasFatal = false;
    int? exitCode;
    String? errorMsg;

    for (final command in commands) {
      if (command.trim().isEmpty) continue;
      final result =
          await _runOne(command, workingDirectory, environment, mirror);
      responses.write('CLI Command: $command\n');
      if (result.exitCode != 0) {
        // Providers print their diagnostics on stdout (run-agent.sh echoes
        // everything); stderr-only error reports hid the actual failure.
        final stdout = result.stdout.trim();
        responses.write('Error: ${result.stderr}\n');
        if (stdout.isNotEmpty) responses.write('Output:\n$stdout\n');
        responses.write('\n');
        hasFatal = true;
        exitCode = result.exitCode;
        errorMsg = result.stderr;
      } else {
        responses.write('Response:\n${result.stdout}\n\n');
      }
    }

    final outputResponse = readOutputResponse(workingDirectory, preference);
    return CliExecutionResult(
      commandResponses: responses.toString(),
      outputResponse: outputResponse,
      hasFatalError: hasFatal,
      lastExitCode: exitCode,
      lastErrorMessage: errorMsg,
    );
  }

  /// Runs a single shell command with live output mirroring.
  Future<CapturedProcessResult> _runOne(
    String command,
    String? workingDirectory,
    Map<String, String>? environment,
    OutputLineSink? mirror,
  ) {
    return runCaptured(
      '/bin/sh',
      ['-c', command.trim()],
      workingDirectory: workingDirectory,
      environment: environment,
      mirror: mirror,
    );
  }

  // ------------------------------------------------------------------
  // Monitored execution (timer / error / line hooks)
  // ------------------------------------------------------------------

  /// Executes [commands] with optional timer/error/line [callbacks].
  ///
  /// When [callbacks] has no hooks, delegates to [executeCommands]. Otherwise
  /// each command is streamed line-by-line (stdout+stderr merged, mirroring the
  /// Java `redirectErrorStream` behaviour) so [CliExecutionCallbacks.lineStopPredicate]
  /// can stop mid-output; a background [Timer] fires [CliExecutionCallbacks.timerAction]
  /// periodically and once more after the batch (final tick). Every streamed
  /// line is mirrored live to dmtools' stderr ([mirror] overrides the target
  /// for tests). Port of Java `executeCliCommandsWithResult`.
  Future<CliExecutionResult> executeCommandsWithCallbacks(
    List<String> commands, {
    String? workingDirectory,
    Map<String, String>? environment,
    CliExecutionCallbacks? callbacks,
    OutputFolderPreference preference = OutputFolderPreference.outputsFirst,
    OutputLineSink? mirror,
  }) async {
    if (callbacks == null || !callbacks.hasHooks) {
      return executeCommands(
        commands,
        workingDirectory: workingDirectory,
        environment: environment,
        preference: preference,
        mirror: mirror,
      );
    }
    final timer = _startTimer(callbacks);
    try {
      final outcome = await _runMonitoredBatch(
        commands,
        workingDirectory,
        environment,
        callbacks,
        mirror,
      );
      return CliExecutionResult(
        commandResponses: outcome.responses,
        outputResponse: readOutputResponse(workingDirectory, preference),
        hasFatalError: outcome.hasFatal,
        lastExitCode: outcome.exitCode,
        lastErrorMessage: outcome.errorMsg,
      );
    } finally {
      timer?.cancel();
      if (callbacks.timerAction != null) callbacks.timerAction!();
    }
  }

  /// Starts the periodic timer for [cb], or `null` when disabled.
  Timer? _startTimer(CliExecutionCallbacks cb) {
    final action = cb.timerAction;
    if (action == null || cb.timerIntervalSeconds <= 0) return null;
    return Timer.periodic(
      Duration(seconds: cb.timerIntervalSeconds),
      (_) {
        try {
          action();
        } catch (e) {
          stderr.writeln('timerJSAction threw (ignored): $e');
        }
      },
    );
  }

  /// Runs the full command batch with monitoring, returning the accumulated
  /// responses and the last fatal-error signal. [mirror] receives every
  /// output line as it streams.
  Future<_BatchOutcome> _runMonitoredBatch(
    List<String> commands,
    String? workDir,
    Map<String, String>? env,
    CliExecutionCallbacks cb,
    OutputLineSink? mirror,
  ) async {
    final responses = StringBuffer();
    var hasFatal = false;
    int? lastExit;
    String? lastErr;
    for (final command in commands) {
      if (command.trim().isEmpty) continue;
      responses.write('CLI Command: $command\n');
      final one = await _runStreamedCommand(
        command,
        workDir,
        env,
        responses,
        cb,
        mirror,
      );
      if (one.stopped) {
        responses.write(
          'Stopped: CLI execution stopped by line callback at line: '
          '${one.stopLine}\n\n',
        );
        break;
      }
      if (one.exitCode != 0) {
        hasFatal = true;
        lastExit = one.exitCode;
        final msg = 'Command failed (exit code ${one.exitCode}): $command\n'
            'Output:\n${one.output.trim()}';
        lastErr = msg;
        responses.write('Error: $msg\n\n');
        cb.errorHandler?.call(msg);
      } else {
        responses.write('Response:\n${one.output}\n\n');
      }
      final live = cb.liveOutput;
      if (live != null) live.value = responses.toString();
    }
    return _BatchOutcome(responses.toString(), hasFatal, lastExit, lastErr);
  }

  /// Streams one command's merged stdout/stderr line-by-line.
  ///
  /// Updates [CliExecutionCallbacks.liveOutput] after each line so a concurrent
  /// timer tick sees partial output, and mirrors every line live via [mirror]
  /// (dmtools' own stderr when null; best-effort, like [safeMirrorLine]).
  /// When the line-stop predicate returns `true`, the process is killed and
  /// execution stops.
  Future<_CommandOutcome> _runStreamedCommand(
    String command,
    String? workDir,
    Map<String, String>? env,
    StringBuffer responses,
    CliExecutionCallbacks cb,
    OutputLineSink? mirror,
  ) async {
    final proc = await Process.start(
      '/bin/sh',
      ['-c', '${command.trim()} 2>&1'],
      workingDirectory: workDir,
      environment: env,
    );
    final output = StringBuffer();
    final lineMirror = mirror ?? mirrorLineToStderr;
    var stopped = false;
    String? stopLine;
    var streamFailed = false;
    // Lenient UTF-8 (allowMalformed: true) matches the buffered path's
    // captureAndMirror decode: malformed child output becomes U+FFFD on
    // both CliAgent paths instead of throwing mid-batch only here.
    try {
      await for (final line in proc.stdout
          .transform(const Utf8Decoder(allowMalformed: true))
          .transform(const LineSplitter())) {
        output.writeln(line);
        safeMirrorLine(lineMirror, line);
        final live = cb.liveOutput;
        if (live != null) live.value = '$responses$output';
        if (cb.lineStopPredicate != null && cb.lineStopPredicate!(line)) {
          stopLine = line;
          stopped = true;
          proc.kill(ProcessSignal.sigkill);
          break;
        }
      }
    } on Object {
      streamFailed = true;
      rethrow;
    } finally {
      // No-op when the process already exited (stdout EOF means the shell
      // has exited, so the success path's exit code is untouched) or when
      // the stop path already SIGKILLed it; kills runaways when the
      // predicate (a JS callback) or the liveOutput setter threw
      // mid-stream, so the child cannot outlive the failed batch detached.
      // The rethrow above propagates only after this await, so the kill is
      // complete when the caller sees the error.
      if (streamFailed) {
        proc.kill(ProcessSignal.sigkill);
      }
      await proc.exitCode;
    }
    final code = await proc.exitCode;
    return _CommandOutcome(output.toString(), code, stopped, stopLine);
  }

  // ------------------------------------------------------------------
  // Output response
  // ------------------------------------------------------------------

  /// Reads the output response file relative to [workingDirectory].
  ///
  /// Checks the folder determined by [preference] first, then falls back
  /// to the other. Returns null when neither file exists or is empty.
  ///
  /// Mirrors `CliExecutionHelper.processOutputResponse()`.
  String? readOutputResponse(
    String? workingDirectory,
    OutputFolderPreference preference,
  ) {
    final base = workingDirectory ?? Directory.current.path;
    final outputsFile = File('$base/outputs/$responseFileName');
    final legacyFile = File('$base/output/$responseFileName');
    final primary = preference == OutputFolderPreference.outputsFirst
        ? outputsFile
        : legacyFile;
    final fallback = preference == OutputFolderPreference.outputsFirst
        ? legacyFile
        : outputsFile;
    return _readFile(primary) ?? _readFile(fallback);
  }

  String? _readFile(File file) {
    if (!file.existsSync()) return null;
    final content = file.readAsStringSync();
    if (content.trim().isEmpty) return null;
    return content;
  }
}

/// Accumulated result of a monitored command batch.
class _BatchOutcome {
  const _BatchOutcome(
    this.responses,
    this.hasFatal,
    this.exitCode,
    this.errorMsg,
  );

  final String responses;
  final bool hasFatal;
  final int? exitCode;
  final String? errorMsg;
}

/// Result of a single streamed command.
class _CommandOutcome {
  const _CommandOutcome(
    this.output,
    this.exitCode,
    this.stopped,
    this.stopLine,
  );

  final String output;
  final int exitCode;
  final bool stopped;
  final String? stopLine;
}

/// Executes a CliAgent job — Dart port of Java `CliAgent`.
///
/// Lifecycle (exact order, mirrors Java `CliAgent.runJobImpl`):
/// ```text
/// setup → preJSAction → preCliJSAction → cliCommands → postJSAction →
/// cache → reset (always runs, even on failure)
/// ```
///
/// Script hooks (`setup`/`cache`/`reset`) run as shell commands unless the
/// path ends with `.js` — then they execute via [JsJobRunner]. JS actions
/// (`preJSAction`/`preCliJSAction`/`postJSAction`) always run via
/// [JsJobRunner]. During the `cliCommands` phase, three further JS actions may
/// fire when configured: `timerJSAction` (periodic, plus a final tick),
/// `cliExecutionErrorJSAction` (on a non-zero exit), and `cliOutputLineJSAction`
/// (per output line; returning `true` stops the batch). Errors in hooks and
/// actions are caught and logged (the lifecycle continues); only CLI command
/// failures can fail the run.
library;

import 'dart:convert';
import 'dart:io';

import '../config/env_file_parser.dart';
import '../config/property_reader.dart';
import '../config/property_reader_getters.dart';
import '../js/job_runner.dart';
import 'cli_agent_params.dart';
import 'cli_command_builder.dart';
import 'cli_execution_helper.dart';
import 'ticket_input_context_builder.dart';

/// Executes a CliAgent job — lightweight CLI-agent orchestrator.
///
/// Takes the CLI-execution parts of `Teammate` and removes the
/// tracker-ticket plumbing: runs cursor-agent / claude / copilot-style CLI
/// tools with aggregated prompts and optional setup/cache/reset hooks,
/// without needing an `inputJql` or a ticket system.
class CliAgent {
  /// Creates a CliAgent with the given [params].
  ///
  /// - [workingDirectory] — overrides `params.workingDirectory` when set.
  /// - [ticketData] — raw tracker ticket JSON for the input context; in a
  ///   real run this is fetched from Jira/ADO via the tracker client.
  /// - [propertyReader] — property resolution; defaults to a new reader.
  /// - [jsRunner] — JS execution engine; defaults to [JsJobRunner].
  CliAgent({
    required this.params,
    this.workingDirectory,
    this.ticketData,
    PropertyReader? propertyReader,
    JsJobRunner? jsRunner,
  })  : propertyReader = propertyReader ?? PropertyReader(),
        jsRunner = jsRunner ?? const JsJobRunner();

  /// Parameters from the job config.
  final CliAgentParams params;

  /// Working-directory override; when null, `params.workingDirectory` or
  /// the CWD is used.
  final String? workingDirectory;

  /// Raw tracker ticket JSON used to populate the input context.
  ///
  /// When null (no tracker configured), the input context folder is created
  /// empty — the ticket-agnostic behavior.
  final Map<String, dynamic>? ticketData;

  /// Property reader for environment resolution.
  final PropertyReader propertyReader;

  /// JS runner for `.js` actions and hooks.
  final JsJobRunner jsRunner;

  /// Result of the `cliCommands` phase — used by the reset hook.
  CliExecutionResult? _cliResult;

  /// Input context path — cleaned up in the finally block.
  String? _inputContextPath;

  /// Ticket data as seen by the JS actions (`params.ticket`).
  ///
  /// Either the tracker-fetched [ticketData] (Teammate job) or, when absent,
  /// `input/<contextId>/ticket.json` loaded by convention (direct
  /// `dmtools run` launches, e.g. the machine's review/rework runners).
  /// Set once at the start of the lifecycle.
  Map<String, dynamic>? _resolvedTicketData;

  /// Runs the full lifecycle. Returns a result map.
  ///
  /// - Success: `{'success': true, 'contextId': …, 'response': …}`
  /// - Failure: `{'success': false, 'error': …}`
  ///
  /// The reset hook and folder cleanup always run (in a `finally` block),
  /// mirroring the Java `runJobImpl` finally semantics.
  Future<Map<String, dynamic>> run() async {
    if (params.cliCommands.isEmpty) {
      return {'success': true, 'message': 'No cliCommands provided'};
    }
    // Zone-scoped overrides: two CliAgent jobs running concurrently in one
    // isolate each keep their own `TrackerParams.envVariables` across
    // awaits (Java gets this from ThreadLocal).
    return PropertyReader.runWithOverrides(
      params.envVariables ?? {},
      _runGuarded,
    );
  }

  /// Runs the lifecycle, converting failures into error results.
  Future<Map<String, dynamic>> _runGuarded() async {
    try {
      return await _runLifecycle(_resolveWorkingDirectory());
    } catch (e) {
      return {'success': false, 'error': e.toString()};
    }
  }

  /// Executes the main lifecycle phases inside [workDir].
  Future<Map<String, dynamic>> _runLifecycle(String workDir) async {
    String? response;
    try {
      _resolvedTicketData = _resolveTicketData(workDir);
      _clearStaleOutputs(workDir);
      await _executeScriptHook('setup', params.setup, workDir, null);
      _executeJsAction('preJSAction', params.preJSAction, null, null, workDir);
      _inputContextPath = _createInputContext(workDir);
      _executeJsAction(
        'preCliJSAction',
        params.preCliJSAction,
        null,
        _inputContextPath,
        workDir,
      );
      response = await _executeCliCommands(workDir);
      _executeJsAction(
        'postJSAction',
        params.postJSAction,
        response,
        _inputContextPath,
        workDir,
      );
      await _executeScriptHook('cache', params.cache, workDir, response);
      return {
        'success': true,
        'contextId': params.contextId,
        'response': response,
      };
    } finally {
      await _executeScriptHook(
        'reset',
        params.reset,
        workDir,
        _cliResult != null ? _extractResponse(_cliResult!) : null,
      );
      _performCleanup(workDir);
    }
  }

  // ------------------------------------------------------------------
  // Script hooks (setup / cache / reset)
  // ------------------------------------------------------------------

  /// Executes a script hook: `.js` path via [JsJobRunner], else shell.
  ///
  /// Errors are caught and logged — the lifecycle continues (mirrors Java
  /// `executeScriptHook`).
  Future<void> _executeScriptHook(
    String name,
    String? script,
    String workDir,
    String? response,
  ) async {
    if (script == null || script.trim().isEmpty) return;
    try {
      if (script.endsWith('.js')) {
        jsRunner.runScript(
          scriptPath: script,
          jobParams: _buildJobParams(response, null),
          workingDirectory: workDir,
          config: JsRunConfig(
            extraGlobals: {'workingDirectory': workDir},
          ),
        );
      } else {
        await _runShell(script, workDir, applyEnvFilters: false);
      }
    } catch (e) {
      stderr.writeln('$name hook failed, continuing: $e');
    }
  }

  /// Runs [command] as a shell command in [workDir].
  Future<void> _runShell(
    String command,
    String workDir, {
    required bool applyEnvFilters,
  }) async {
    final env = _buildSubprocessEnvironment(workDir, applyEnvFilters);
    await Process.run(
      '/bin/sh',
      ['-c', command.trim()],
      workingDirectory: workDir,
      environment: env,
    );
  }

  // ------------------------------------------------------------------
  // JS actions (preJSAction / preCliJSAction / postJSAction)
  // ------------------------------------------------------------------

  /// Executes a JS action via [JsJobRunner] with context bindings.
  ///
  /// Errors are caught and logged — the lifecycle continues (mirrors Java
  /// `executeJsAction`).
  void _executeJsAction(
    String name,
    String? actionPath,
    String? response,
    String? inputFolderPath,
    String workDir,
  ) {
    if (actionPath == null || actionPath.trim().isEmpty) return;
    try {
      jsRunner.runScript(
        scriptPath: actionPath,
        jobParams: _buildJobParams(response, inputFolderPath),
        ticket: _resolvedTicketData ?? ticketData,
        workingDirectory: workDir,
        config: JsRunConfig(
          extraGlobals: _buildExtraGlobals(response, inputFolderPath, workDir),
        ),
      );
    } catch (e) {
      stderr.writeln('$name failed, continuing: $e');
    }
  }

  // ------------------------------------------------------------------
  // CLI command phase
  // ------------------------------------------------------------------

  /// Builds and executes CLI commands, returning the extracted response.
  ///
  /// When any of `timerJSAction`, `cliExecutionErrorJSAction`, or
  /// `cliOutputLineJSAction` is configured, commands run through the monitored
  /// path ([CliExecutionHelper.executeCommandsWithCallbacks]) so the hooks fire
  /// periodically / per-line / on error. Otherwise the buffered path is used.
  Future<String> _executeCliCommands(String workDir) async {
    final builder = const CliCommandBuilder();
    final finalCommands = builder.buildCommands(
      params.cliCommands,
      params.cliPrompt,
      params.cliPromptsAsArray,
      params.cliPromptsByTracker,
      trackerType: propertyReader.getDefaultTracker(),
      workingDirectory: workDir,
    );
    _ensureOutputFolder(workDir);
    final env = _buildSubprocessEnvironment(workDir, true);
    final live = LiveCliOutput();
    final callbacks = _buildCliCallbacks(workDir, live);
    final helper = const CliExecutionHelper();
    _cliResult = callbacks == null
        ? await helper.executeCommands(
            finalCommands,
            workingDirectory: workDir,
            environment: env,
          )
        : await helper.executeCommandsWithCallbacks(
            finalCommands,
            workingDirectory: workDir,
            environment: env,
            callbacks: callbacks,
          );
    return _extractResponse(_cliResult!);
  }

  // ------------------------------------------------------------------
  // Context JS actions (timer / error / line)
  // ------------------------------------------------------------------

  /// Builds CLI-execution callbacks for the timer/error/line JS actions, or
  /// `null` when none are configured.
  CliExecutionCallbacks? _buildCliCallbacks(
    String workDir,
    LiveCliOutput live,
  ) {
    final timer = _buildTimerAction(workDir, live);
    final error = _buildErrorHandler(workDir, live);
    final stop = _buildLineStopPredicate(workDir, live);
    if (timer == null && error == null && stop == null) return null;
    return CliExecutionCallbacks(
      timerAction: timer,
      timerIntervalSeconds: params.timerIntervalSeconds,
      errorHandler: error,
      lineStopPredicate: stop,
      liveOutput: live,
    );
  }

  /// Builds the periodic timer callback (Java `buildTimerRunnable`).
  void Function()? _buildTimerAction(String workDir, LiveCliOutput live) {
    final action = params.timerJSAction;
    if (action == null || action.trim().isEmpty) return null;
    return () => _runContextJsAction(
          'timerJSAction',
          action,
          workDir,
          {'currentCliOutput': live.value},
        );
  }

  /// Builds the CLI-failure callback (Java `buildErrorHandler`).
  void Function(String)? _buildErrorHandler(
      String workDir, LiveCliOutput live) {
    final action = params.cliExecutionErrorJSAction;
    if (action == null || action.trim().isEmpty) return null;
    return (String errorMessage) => _runContextJsAction(
          'cliExecutionErrorJSAction',
          action,
          workDir,
          {'errorMessage': errorMessage, 'currentCliOutput': live.value},
        );
  }

  /// Builds the per-line stop predicate (Java `buildLineStopPredicate`).
  bool Function(String)? _buildLineStopPredicate(
    String workDir,
    LiveCliOutput live,
  ) {
    final action = params.cliOutputLineJSAction;
    if (action == null || action.trim().isEmpty) return null;
    return (String line) {
      final result = _runContextJsAction(
        'cliOutputLineJSAction',
        action,
        workDir,
        {'line': line, 'currentCliOutput': live.value},
      );
      return result?.toLowerCase() == 'true';
    };
  }

  /// Runs a context JS action via [JsJobRunner], injecting [context] globals.
  ///
  /// Returns the JSON-serialized result (for line-stop boolean parsing).
  /// Errors are caught and logged — the lifecycle continues — mirroring the
  /// Java `executeJsAction` / `buildLineStopPredicate` swallow-and-continue
  /// contract.
  String? _runContextJsAction(
    String name,
    String actionPath,
    String workDir,
    Map<String, dynamic> context,
  ) {
    try {
      return jsRunner.runScript(
        scriptPath: actionPath,
        jobParams: _buildJobParams(null, null),
        ticket: _resolvedTicketData ?? ticketData,
        workingDirectory: workDir,
        config: JsRunConfig(
          extraGlobals: _mergeContextGlobals(context, workDir),
        ),
      );
    } catch (e) {
      stderr.writeln('$name failed, continuing: $e');
      return null;
    }
  }

  /// Merges the standard JS action globals with action-specific [context].
  Map<String, dynamic> _mergeContextGlobals(
    Map<String, dynamic> context,
    String workDir,
  ) {
    return {..._buildExtraGlobals(null, null, workDir), ...context};
  }

  /// Extracts the response from the CLI result.
  ///
  /// Mirrors Java `extractResponse`: `requireCliOutputFile` turns a missing
  /// output file into an error; the output file content is preferred;
  /// command responses are the fallback.
  ///
  /// Deliberate deviation from Java (gh-192): a failed run's fallback is a
  /// [boundedLog] excerpt, not the full `commandResponses` — post-actions
  /// publish the response verbatim as PR/ticket comments, and the full
  /// session log of a failed agent must never be posted that way. Java
  /// still returns the full log here; this repo intentionally does not.
  String _extractResponse(CliExecutionResult result) {
    if (params.requireCliOutputFile && !result.hasOutputResponse) {
      return 'CLI command executed but did not produce output file:\n'
          '${boundedLog(result.commandResponses)}';
    }
    if (result.hasOutputResponse) {
      return result.outputResponse!;
    }
    if (result.hasFatalError) {
      return 'CLI command failed (exit code ${result.lastExitCode ?? 'unknown'}) '
          'and did not produce $responseFileName — the full session log is '
          'excluded from this response (see the run output). Bounded excerpt:\n'
          '${boundedLog(result.commandResponses)}';
    }
    return result.commandResponses;
  }

  // ------------------------------------------------------------------
  // Environment
  // ------------------------------------------------------------------

  /// Builds the subprocess environment.
  ///
  /// Starts from the OS env, overlays `dmtools.env` from [workDir], then
  /// the per-job `envVariables` overrides. When [applyEnvFilters] is true,
  /// the `excludedEnvVariables`/`excludeEnvVariablesByRegex` filters are
  /// applied (CLI command phase only — script hooks do not filter).
  Map<String, String> _buildSubprocessEnvironment(
    String workDir,
    bool applyEnvFilters,
  ) {
    var env = <String, String>{}
      ..addAll(Platform.environment)
      ..addAll(parseEnvFile('$workDir/dmtools.env'))
      ..addAll(PropertyReader.getOverrides());
    if (applyEnvFilters) {
      env = CliExecutionHelper.filterEnvVariables(
        env,
        params.excludedEnvVariables,
        params.excludeEnvVariablesByRegex,
      );
    }
    return env;
  }

  // ------------------------------------------------------------------
  // Filesystem operations
  // ------------------------------------------------------------------

  /// Resolves the working directory (param → existing dir → CWD).
  String _resolveWorkingDirectory() {
    final candidate = workingDirectory ?? params.workingDirectory;
    if (candidate != null && candidate.trim().isNotEmpty) {
      final dir = Directory(candidate);
      if (dir.existsSync()) {
        return dir.absolute.path;
      }
    }
    return Directory.current.absolute.path;
  }

  /// Deletes stale `outputs/response.md` and `output/response.md`.
  void _clearStaleOutputs(String workDir) {
    _deleteFileIfPresent(File('$workDir/outputs/$responseFileName'));
    _deleteFileIfPresent(File('$workDir/output/$responseFileName'));
  }

  /// Deletes [file] when it exists; errors are ignored.
  void _deleteFileIfPresent(File file) {
    if (file.existsSync()) {
      file.deleteSync();
    }
  }

  /// Creates the input context folder: `input/<contextId>/`.
  ///
  /// When resolved ticket data is set (fetched from a tracker, or loaded by
  /// convention from `input/<contextId>/ticket.json`), the folder is
  /// populated with `ticket.md`, `ticket.json`, `subtasks/`, and
  /// `comments.md` via [TicketInputContextBuilder]. Otherwise an empty
  /// folder is created — the ticket-agnostic behavior.
  String _createInputContext(String workDir) {
    return TicketInputContextBuilder(workDir).build(
      params.contextId,
      ticketData: _resolvedTicketData ?? ticketData,
    );
  }

  /// Resolves the ticket data for the JS `params.ticket` contract.
  ///
  /// [ticketData] (fetched by the Teammate job) wins. Otherwise a direct
  /// `dmtools run` launch may still carry a ticket by convention: the CI
  /// integration pre-writes `input/<contextId>/ticket.json` (the same file
  /// [TicketInputContextBuilder] produces) before the run. Loading it keeps
  /// `params.ticket.key` / `params.ticketKey` — and every JS action that
  /// reads them (timer auto-commit, post-JS hooks) — working identically
  /// for GitHub-issue runs and Jira runs. A malformed or missing file
  /// behaves as "no ticket".
  Map<String, dynamic>? _resolveTicketData(String workDir) {
    if (ticketData != null) return ticketData;
    if (params.contextId.isEmpty) return null;
    final file = File('$workDir/input/${params.contextId}/ticket.json');
    if (!file.existsSync()) return null;
    try {
      final decoded = jsonDecode(file.readAsStringSync());
      return decoded is Map<String, dynamic> ? decoded : null;
    } catch (_) {
      return null;
    }
  }

  /// Ensures the `outputs/` folder exists before CLI commands run.
  void _ensureOutputFolder(String workDir) {
    Directory('$workDir/outputs').createSync(recursive: true);
  }

  /// Cleans up the input and outputs folders per params flags.
  ///
  /// Mirrors the Java `finally` block cleanup logic.
  void _performCleanup(String workDir) {
    final inputPath = _inputContextPath;
    if (inputPath != null && params.cleanupInputFolder) {
      _deleteDirectory(Directory(inputPath));
    }
    if (params.cleanupOutputsFolder) {
      _deleteDirectory(Directory('$workDir/outputs'));
      _deleteDirectory(Directory('$workDir/output'));
    }
  }

  /// Recursively deletes [dir] if it exists.
  void _deleteDirectory(Directory dir) {
    if (dir.existsSync()) {
      dir.deleteSync(recursive: true);
    }
  }

  // ------------------------------------------------------------------
  // JS context building
  // ------------------------------------------------------------------

  /// Builds the job-params map passed as `params.jobParams` to JS actions.
  Map<String, dynamic> _buildJobParams(
    String? response,
    String? inputFolderPath,
  ) {
    return {
      'cliCommands': params.cliCommands,
      if (params.cliPrompt != null) 'cliPrompt': params.cliPrompt,
      if (params.contextId.isNotEmpty) 'contextId': params.contextId,
      if (response != null) 'response': response,
      if (inputFolderPath != null) 'inputFolderPath': inputFolderPath,
    };
  }

  /// Builds the extra top-level JS globals for JS actions.
  ///
  /// Mirrors Java `prepareJsExecutor` `.with()` bindings.
  Map<String, dynamic> _buildExtraGlobals(
    String? response,
    String? inputFolderPath,
    String workDir,
  ) {
    return {
      if (response != null) 'response': response,
      if (inputFolderPath != null) 'inputFolderPath': inputFolderPath,
      'workingDirectory': workDir,
      if (params.customParams != null) 'customParams': params.customParams,
    };
  }
}

