    String? workingDirectory,
    Map<String, String>? environment,
    OutputFolderPreference preference = OutputFolderPreference.outputsFirst,
    OutputLineSink? mirror,
  }) async {
    final responses = StringBuffer();
    var hasFatal = false;
    int? exitCode;
