+// ======================================================================
+
+void boundedLogTests() {
+  group('boundedLog', () {
+    test('returns short logs unchanged', () {
+      const log = 'CLI Command: echo hi\nResponse:\nhi';
+      expect(boundedLog('$log\n'), log);
+    });
